def normalize_phone(s: str) -> str:
    import re
    match = re.fullmatch(r'\d{3}-\d{3}-\d{4}', s)
    if match:
        return f'({match.group(0)[:3]}) {match.group(0)[4:7]}-{match.group(0)[8:]}'
    match = re.fullmatch(r'\(\d{3}\) \d{3} \d{4}', s)
    if match:
        return f'{match.group(0)[1:4]}-{match.group(0)[5:8]}-{match.group(0)[9:13]}'
    return s

